import { useEffect, useState } from 'react';

/**
 * Weekly scores, generated by scripts/schedule_content.py from data/y80/schedules.json (schedule.set):
 * public/data/league/schedule.json. Rules only; the site never edits it.
 */
export const SCHEDULE_URL = `${import.meta.env.BASE_URL}data/league/schedule.json`;

export interface CoachGame {
  week: number;
  /** "Week 3", "Bye", "Divisional", "Conference", "Super Bowl" … */
  round: string;
  site?: 'home' | 'away';
  /** Opponent nickname ("Commanders") and abbreviation ("WAS") */
  opp?: string;
  oppAbbr?: string;
  for?: number;
  against?: number;
  result?: 'W' | 'L' | 'T';
  margin?: number;
  /** Winner's score first ("48-23") */
  score?: string;
  /** Opponent's final record ("11-5-1") and the season summary screen's offense / defense ratings (0–5 stars) */
  oppRecord?: string;
  oppOff?: number;
  oppDef?: number;
  playoff?: boolean;
}

export interface TableRow {
  team: string;
  abbr: string;
  conference?: string | null;
  division?: string | null;
  divisionRank?: number | null;
  w: number;
  l: number;
  t: number;
  record: string;
  pct: number;
  pf: number;
  pa: number;
  diff: number;
  ppg: number;
  papg: number;
  /** Strength of schedule: average final win % of the clubs it played */
  sos: number;
  /** 100 × win % + 1.5 × diff per game + 40 × (SOS − 0.5) */
  powerScore: number;
  power: number;
}

export interface GameRef {
  week: number;
  away: string;
  home: string;
  awayScore: number;
  homeScore: number;
  winner: string | null;
  loser: string | null;
  score: string;
  margin: number;
  total: number;
  winnerRecord?: string;
  loserRecord?: string;
}

export interface ScheduleSeason {
  season: string;
  coachTeam: string;
  coachAbbr: string;
  coachRecord: { w: number; l: number; t: number; pf: number; pa: number; diff: number; power: number; record: string; playoffs: string };
  coachGames: CoachGame[];
  table: TableRow[];
  leaders: { bestOffense: string; bestDefense: string; worstDefense: string; bestDiff: string };
  upset?: GameRef;
  blowout?: GameRef;
  shootout?: GameRef;
  games: { week: number; away: string; home: string; awayScore: number; homeScore: number }[];
  regularSeasonGames: number;
}

export interface HeadToHead {
  team: string;
  w: number;
  l: number;
  t: number;
  record: string;
  games: number;
  meetings: { season: string; week: number; round: string; site: string; coachTeam: string; for: number; against: number; result: 'W' | 'L' | 'T' }[];
}

export interface GameRecord {
  id: string;
  label: string;
  value: number;
  season?: string;
  week?: number;
  away?: string;
  home?: string;
  awayScore?: number;
  homeScore?: number;
  team?: string;
}

export interface Schedule {
  seasons: Record<string, ScheduleSeason>;
  headToHead: Record<string, HeadToHead>;
  records: GameRecord[];
}

const EMPTY: Schedule = { seasons: {}, headToHead: {}, records: [] };

let request: Promise<Schedule> | null = null;
/** Fetches schedule.json once per page load (revalidated, like every data file). A missing file is an empty schedule. */
export const loadSchedule = (): Promise<Schedule> => {
  request ??= fetch(SCHEDULE_URL, { cache: 'no-cache' })
    .then((res) => (res.ok ? res.json() : EMPTY))
    .then((json: Partial<Schedule>) => ({ ...EMPTY, ...json }))
    .catch(() => EMPTY);
  return request;
};

/** Seasons with weekly scores, newest first. */
export const scheduleSeasons = (s: Schedule): ScheduleSeason[] =>
  Object.values(s.seasons).sort((a, b) => Number(b.season.slice(1)) - Number(a.season.slice(1)));

/** The newest season with weekly scores, or null when there are none. */
export const latestScheduleSeason = (s: Schedule): ScheduleSeason | null => scheduleSeasons(s)[0] ?? null;

/** A club's season in one line: record and point differential ("15-2, +119"). */
export const formLine = (row: Pick<TableRow, 'record' | 'diff'>) => `${row.record}, ${row.diff > 0 ? '+' : ''}${row.diff}`;

export const useSchedule = () => {
  const [schedule, setSchedule] = useState<Schedule | null>(null);
  useEffect(() => {
    let cancelled = false;
    loadSchedule().then((s) => {
      if (!cancelled) setSchedule(s);
    });
    return () => {
      cancelled = true;
    };
  }, []);
  return schedule;
};
